// Creation context, list data and accessible modal behavior share explicit state.
state.creationFlow=false;
function creationContext(){return state.creationFlow&&!state.gameDraftMode&&['event-basic','templates','editor','prizes','review','publish','checkout'].includes(route())}
const qaBeginEvent=beginEvent;beginEvent=function(brand=''){state.creationFlow=true;state.gameDraftMode=false;qaBeginEvent(brand)};
const qaSubmitBasics=submitBasics;submitBasics=function(e){state.creationFlow=true;qaSubmitBasics(e);if(route()!=='event-basic')retainEvent()};
const qaOpenEvent=openWorkspaceEvent;openWorkspaceEvent=function(n){state.creationFlow=false;qaOpenEvent(n)};
const qaShell=shell;shell=function(body){if(!creationContext())return qaShell(body);body=body.replace(/<div class="creation-steps"[\s\S]*?<\/div>/g,'');let h=qaShell(body);h=h.replace(/<div class="breadcrumbs">[\s\S]*?<\/div>/,`<div class="breadcrumbs"><strong>행사 만들기</strong>${state.eventName?`<span>/</span><span>${esc(state.eventName)}</span>`:''}</div>`);return h.replace(/(<button class="btn [^"]*" data-action="new")/, '$1 aria-current="page"').replace(/(<a href="#templates" class=")[^"]*(")/,'$1$2')};
const qaTemplates=templates;templates=function(){let h=qaTemplates();if(creationContext()){h=h.replace(/<div class="creation-steps"[\s\S]*?<\/div>/g,'');}return h};
const qaGallery=galleryCards;galleryCards=function(){let h=qaGallery();if(h.includes('class="empty-gallery"')){const noFavorites=state.templateFilter==='즐겨찾기'&&!gameTemplates.some(t=>state.favorites.includes(t.id));h=`<div class="empty-gallery">${noFavorites?'즐겨찾기한 템플릿이 없어요.':state.templateFilter==='즐겨찾기'?'즐겨찾기에서 검색 결과를 찾지 못했어요.':'검색 결과가 없습니다.'}</div>`}return h.replace(/(<button\b[^>]*data-favorite="([^"]+)"[^>]*)(>)/g,(_,tag,id,end)=>tag.replace(/ aria-pressed="[^"]*"/g,'')+` aria-pressed="${state.favorites.includes(id)}"`+end)};
const qaRetain=retainEvent;retainEvent=function(){qaRetain();if(state.eventName&&!state.gameDraftMode){const e=eventData.find(e=>e[0]===state.eventName&&e[1]===currentBrand().short);if(e)e[4]=eventPeriod(state.basic)||e[4]}};
const qaEventTable=eventTable;eventTable=function(){for(const r of allEventRows())r.e[4]=eventPeriod(r.record.basic)||r.e[4];return qaEventTable()};
const qaBrandRows=brandRows;brandRows=function(b,sending){let h=qaBrandRows(b,sending);if(!sending){const template=document.createElement('template');template.innerHTML=h;template.content.querySelectorAll('[data-open-event]').forEach(tr=>{const record=state.eventMemory[eventKey(b.id,tr.dataset.openEvent)];if(record&&tr.cells[3])tr.cells[3].textContent=eventPeriod(record.basic)});h=template.innerHTML}return h};
function siteLink(screen){return location.origin+location.pathname+'#'+screen}
const qaBranding=whitelabel;whitelabel=function(){return qaBranding().replaceAll('stageone.서비스도메인/lumiere',esc(siteLink('brand-report'))).replaceAll('play.서비스도메인/lumiere',esc(siteLink('start'))).replace('<section class="panel"><div class="panel-head"><h2>고객 화면 미리보기','<section class="panel branding-live-preview" style="--preview-brand:'+state.agencyColor+'"><div class="panel-head"><h2>고객 화면 미리보기')};
// A dialog owns focus until dismissed; restore the exact card/button that opened it.
let qaModalOpener=null,qaModal=null;
function modalFocusables(){return qaModal?[...qaModal.querySelectorAll('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]')].filter(n=>n.getClientRects().length):[]}
function activateModal(){const modal=document.querySelector('.modal-overlay:last-of-type [role="dialog"]');if(!modal||qaModal===modal)return;qaModal=modal;modal.tabIndex=-1;const nodes=modalFocusables();(nodes.find(n=>n.matches('[aria-label="닫기"]'))||nodes[0]||modal).focus()}
function closeQaModal(){const overlay=qaModal?.closest('.modal-overlay');overlay?.remove();qaModal=null;if(qaModalOpener?.isConnected)qaModalOpener.focus();qaModalOpener=null}
const qaPreview=previewTemplate;previewTemplate=function(id){qaModalOpener=document.activeElement;qaPreview(id);activateModal()};
const qaCloseCreate=createAction;createAction=function(a){if(a==='close'&&qaModal){closeQaModal();return}qaCloseCreate(a)};
document.addEventListener('keydown',e=>{if(!qaModal?.isConnected){qaModal=null;return}if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();closeQaModal()}else if(e.key==='Tab'){const nodes=modalFocusables(),first=nodes[0],last=nodes.at(-1);if(!first){e.preventDefault();qaModal.focus()}else if(e.shiftKey&&(document.activeElement===first||document.activeElement===qaModal)||!qaModal.contains(document.activeElement)){e.preventDefault();(e.shiftKey?last:first).focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}},true);
function failureIds(row){const settings=row.record.settings;if(!settings.failureIds||settings.failureIds.length!==taskCounts(row).failed)settings.failureIds=Array.from({length:taskCounts(row).failed},(_,i)=>i);return settings.failureIds}
function failedDeliveries(){return allEventRows().filter(r=>r.flow.status!=='종료').flatMap(row=>failureIds(row).map(id=>({row,id,recipient:'010-****-'+String(1000+id),prize:id%3===0?'할인 쿠폰':'커피 상품권'})))}
function failedDeliveryTable(rows,allBrands=false){return `<div class="table-wrap"><table><thead><tr>${allBrands?'<th>브랜드 · 행사</th>':'<th>선택</th>'}<th>수신 번호</th><th>경품</th><th>실패 사유</th><th>발송 상태</th></tr></thead><tbody>${rows.map(f=>`<tr>${allBrands?`<td><small>${esc(f.row.brand.short)}</small><br><button class="text-link" data-failure-event="${esc(f.row.e[0])}" data-failure-brand="${f.row.brand.id}">${esc(f.row.e[0])}</button></td>`:`<td><input type="checkbox" data-failure-id="${f.id}" checked aria-label="${f.recipient} 재발송 선택"></td>`}<td>${f.recipient}</td><td>${esc(f.prize)}</td><td>일시적 발송 오류</td><td>발송 실패</td></tr>`).join('')||'<tr><td colspan="5">발송 실패가 없습니다.</td></tr>'}</tbody></table></div>`}
function openFailedDeliveries(){qaModalOpener=document.activeElement;const rows=failedDeliveries();app.insertAdjacentHTML('beforeend',`<div class="modal-overlay"><section class="modal send-history-modal" role="dialog" aria-modal="true" aria-labelledby="failed-deliveries-title"><div class="panel-head"><div><h2 id="failed-deliveries-title">발송 실패 확인 · ${rows.length}건</h2><p class="mini-label">${new Set(rows.map(r=>eventKey(r.row.brand.id,r.row.e[0]))).size}개 행사</p></div><button data-qa-close aria-label="닫기">${uiIcon('close')}</button></div>${failedDeliveryTable(rows,true)}</section></div>`);bind();activateModal()}
const qaOperate=operate;operate=function(){let h=qaOperate();const row=allEventRows().find(r=>r.brand.id===state.brandId&&r.e[0]===state.eventName),rows=row?failureIds(row).map(id=>({row,id,recipient:'010-****-'+String(1000+id),prize:id%3===0?'할인 쿠폰':'커피 상품권'})):[];return h.replace(/<section class="panel mt"><div class="panel-head"><h2>발송 실패[\s\S]*?<div class="between mt">/,`<section class="panel mt"><div class="panel-head"><h2>발송 실패 <span>${rows.length}</span></h2><button class="btn secondary" data-action="retry" ${rows.length?'':'disabled'}>선택 건 재발송</button></div>${failedDeliveryTable(rows)}<div class="between mt">`)};
const qaAction=action;action=function(a,n){if(a==='retry'){const row=allEventRows().find(r=>r.brand.id===state.brandId&&r.e[0]===state.eventName);if(!row)return;const selected=[...app.querySelectorAll('[data-failure-id]:checked')].map(n=>+n.dataset.failureId);if(!selected.length)return toast('재발송할 건을 선택해주세요.');const remaining=failureIds(row).filter(id=>!selected.includes(id));state.settings.failureIds=remaining;state.settings.failedCount=remaining.length;state.retried=remaining.length===0;retainEvent();render();toast(selected.length+'건을 가상 재발송했습니다.');return}qaAction(a,n)};
const qaSendingRows=sendingRows;sendingRows=function(){const rows=qaSendingRows(),record=state.eventMemory[eventKey(state.brandId,state.eventName)];if(record?.settings.failureIds)for(const row of rows)row.status=record.settings.failureIds.includes(Number(row.recipient.slice(-4))-1000)?'발송 실패':'발송 완료';return rows};
const qaBind=bind;bind=function(){qaBind();app.querySelectorAll('[data-failure-event]').forEach(n=>n.onclick=()=>{closeQaModal();openWorkspaceEvent({dataset:{eventBrand:n.dataset.failureBrand,openEvent:n.dataset.failureEvent}})});app.querySelectorAll('[data-qa-close]').forEach(n=>n.onclick=closeQaModal);app.querySelectorAll('.sidebar nav a,.logo').forEach(n=>{const click=n.onclick;n.onclick=e=>{state.creationFlow=false;if(click)click(e)}});const color=document.getElementById('agency-color');if(color)color.oninput=()=>{const preview=app.querySelector('.branding-live-preview');preview?.style.setProperty('--preview-brand',color.value);const logo=preview?.querySelector('.external-logo');if(logo)logo.style.color=color.value};};
const pageTitles={home:'홈',events:'전체 행사',workspace:'워크스페이스','workspace-detail':'워크스페이스',templates:'게임 템플릿','event-basic':'행사 만들기',editor:'게임 제작',prizes:'경품·수령',review:'브랜드 검토',publish:'게시 준비',checkout:'행사 패스',operate:'행사 운영',report:'성과 리포트',whitelabel:'브랜딩 설정','brand-review':'브랜드 게임 검토','brand-report':'행사 성과','game-draft':'게임 초안',start:'참여 정보',game:'게임 참여',result:'참여 결과',design:'디자인 보드'};
const qaRender=render;render=function(){qaRender();document.title=(creationContext()?'행사 만들기':pageTitles[route()]||'홈')+' · 두잇킷';if(qaModal&&!qaModal.isConnected){qaModal=null;qaModalOpener=null}};
render();
// Save feedback and reversible event-pass activation.
function editorSaveSignature(){const settings=Object.fromEntries(Object.entries(state.settings).filter(([key])=>!['savedEditorSignature','designSaved','reviewRequested','reportTiming','reportAt','reportScheduledAt','reportShared','endedAutomatically','reviewApproval','reviewComments','openComments','failedCount','failureIds','demoScenario','demoInitialized','demoTraffic','billing'].includes(key)));return JSON.stringify({template:state.selectedTemplate,draft:state.gameDraft,pages:{...state.pageLayers,[state.studioPage]:state.layers},basic:state.basic,settings,consent:state.consent})}
function editorSaved(){return !!state.settings.savedEditorSignature&&state.settings.savedEditorSignature===editorSaveSignature()}
function updateSaveButtons(){if(!['editor','prizes','game-draft'].includes(route()))return;app.querySelectorAll('[data-action="save"]').forEach(n=>{n.textContent=editorSaved()?'저장됨':'저장';n.disabled=editorSaved()})}
const savedEditorView=editor;editor=function(p=false){return savedEditorView(p).replace(/(<button[^>]*data-action="save"[^>]*>)저장(<\/button>)/g,(_,start,end)=>start.replace('>',editorSaved()?' disabled>':'>')+(editorSaved()?'저장됨':'저장')+end)};
const cancelPassPublish=publish;publish=function(){let h=cancelPassPublish();if(state.paid&&!state.published)h=h.replace(/<span class="ready-check">✓ 활성화됨<\/span>/,'<div class="inline"><span class="ready-check">활성화됨</span><button class="btn secondary" data-action="cancel-pass">활성화 취소</button></div>');if(state.paid)h=h.replace('<div class="pass-status">','<div class="pass-status is-active">').replace(/<span class="ready-check">(?:✓ )?활성화됨<\/span>/g,'');return h.replaceAll('행사 패스이','행사 패스가').replaceAll('행사 패스을','행사 패스를').replace('이 행사에 행사 패스가 활성화되어 있습니다.','행사 패스가 활성화되었습니다.')};
const detailAction=action;action=function(a,n){if(a==='cancel-pass'){if(state.published)return toast('게시 중인 행사는 운영 화면에서 먼저 종료해주세요.');state.paid=false;retainEvent();render();toast('행사 패스 활성화를 취소했습니다.');return}if(a==='save'){if(state.prizeError)return toast('경품 확률을 수정한 뒤 저장해주세요.');detailAction(a,n);state.settings.savedEditorSignature=editorSaveSignature();retainEvent();render();return}detailAction(a,n)};
const detailBind=bind;bind=function(){detailBind();const color=document.getElementById('agency-color');if(color){const update=color.oninput;color.oninput=()=>{update?.();app.querySelectorAll('.branding-live-preview .bar').forEach(bar=>bar.style.backgroundColor=color.value)}}app.oninput=updateSaveButtons;app.onchange=updateSaveButtons;updateSaveButtons();document.title=(creationContext()?'행사 만들기':pageTitles[route()]||'홈')+' · 두잇킷'};
// Inline preview colors also survive CSS fallback and older stylesheet caches.
const coloredBrandingView=whitelabel;whitelabel=function(){let i=0;return coloredBrandingView().replace(/(<div class="bar" style=")/g,(_,tag)=>tag+'background:'+state.agencyColor+';opacity:'+([3,4].includes(i++)?'1':'.3')+';')};
window.addEventListener('hashchange',()=>{document.title=(creationContext()?'행사 만들기':pageTitles[route()]||'홈')+' · 두잇킷'});
render();

// Approved review status belongs above the review contents, beside its next action.
const prominentReview=review;review=function(){let h=prominentReview();if(!approvalCurrent())return h;const footer=h.match(/<div class="review-footer mt">([\s\S]*?)<\/div>/);if(!footer)return h;const action=footer[1].replace('<span class="ready-check">현재 시안과 경품 설정이 확정되었습니다.</span>','');h=h.replace(footer[0],'');return h.replace('<div class="review-heading">',statusNotice('확정 완료','현재 시안과 경품 설정이 확정되었습니다.',action,'게임 확정 상태')+'<div class="review-heading">')};
render();
